"""Reusable Streamlit UI component for rendering the Explain Results feature."""

from typing import Any, Dict, Optional
import streamlit as st

from ecg_lab.explanations.schemas import ExplanationPayload, ExplanationResult
from ecg_lab.explanations.service import explain_results

DISCLAIMER_EXPLANATION_BANNER = (
    "**AI-Generated Explanation of Research Software Output:** "
    "This plain-language explanation is generated by an AI language model from computed algorithm metrics. "
    "It is NOT a clinical diagnosis, medical evaluation, or treatment advice. "
    "Machine learning predictions can be inaccurate. Never make health decisions based on this research prototype."
)


def render_explanation_panel(result: ExplanationResult, title: str = "AI Result Explanation") -> None:
    """Render a structured explanation card in Streamlit."""
    status_color = "#10B981" if result.success else "#F59E0B"
    cached_tag = " · Cached" if result.cached else ""

    st.markdown(
        f"""
        <div class='clean-card' style='border-left: 4px solid {status_color}; margin-top: 1.2rem; margin-bottom: 1.2rem;'>
            <div style='display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;'>
                <strong style='font-size: 1.05rem;'>{title}</strong>
                <span style='font-size: 0.78rem; color: #666; font-family: monospace;'>
                    Research Prototype{cached_tag}
                </span>
            </div>
            <p style='font-size: 0.84rem; color: #4B5563; line-height: 1.5; margin-bottom: 0.8rem;'>
                {DISCLAIMER_EXPLANATION_BANNER}
            </p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    if not result.success:
        st.warning(f"**Explanation Notice:** {result.simple_terms}")
        if result.error_message:
            st.caption(f"Details: `{result.error_message}`")
        return

    # Render structured sections in clean cards
    col_a, col_b = st.columns(2)
    with col_a:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem;'>
                <span class='concept-badge'>01 · IN SIMPLE TERMS</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.simple_terms}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )
    with col_b:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem;'>
                <span class='concept-badge'>02 · WHAT THE NUMBERS MEAN</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.what_numbers_mean}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )

    col_c, col_d = st.columns(2)
    with col_c:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem;'>
                <span class='concept-badge'>03 · WHAT STANDS OUT</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.what_stands_out}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )
    with col_d:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem;'>
                <span class='concept-badge'>04 · IMPORTANT LIMITATIONS</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.limitations}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )

    col_e, col_f = st.columns(2)
    with col_e:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem; border-left: 3px solid #DC2626;'>
                <span class='concept-badge' style='color: #DC2626;'>05 · WHAT THIS DOES NOT TELL YOU</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.what_this_does_not_tell_you}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )
    with col_f:
        st.markdown(
            f"""
            <div class='clean-card' style='height: 100%; margin-bottom: 0.8rem; border-left: 3px solid #2563EB;'>
                <span class='concept-badge' style='color: #2563EB;'>06 · SUGGESTED NEXT STEP</span>
                <p style='font-size: 0.88rem; line-height: 1.6; color: #1F2937; margin-top: 0.4rem;'>
                    {result.suggested_next_step}
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )

    st.markdown(
        "<div style='font-size: 0.78rem; color: #9CA3AF; margin-top: 0.5rem; text-align: right;'>"
        "<b>Privacy Notice:</b> Only a minimal, sanitized summary of computed metrics was processed. "
        "No raw ECG voltage traces, patient identifiers, or scanned images are transmitted."
        "</div>",
        unsafe_allow_html=True,
    )


def render_explain_results_button(
    workflow: str,
    payload_data: Dict[str, Any],
    result_id: str,
    title: str = "AI Result Explanation",
    button_key: Optional[str] = None,
) -> None:
    """Render the 'Explain Results' action button and display output when requested.

    Args:
        workflow: Workflow identifier (e.g. 'workflow_b_12lead').
        payload_data: Sanitized dictionary representing the analysis outputs.
        result_id: Unique string identifying the specific run/slice/record.
        title: Title for the rendered explanation panel.
        button_key: Streamlit widget key.
    """
    state_key = f"explain_{workflow}_{result_id}"
    actual_btn_key = button_key or f"btn_explain_{workflow}_{result_id}"

    btn_col1, _ = st.columns([2, 5])
    with btn_col1:
        explain_clicked = st.button(
            "Explain Results",
            key=actual_btn_key,
            help="Generate a plain-language explanation of these computed results.",
        )

    if explain_clicked:
        with st.spinner("Generating explanation..."):
            res = explain_results(payload_data)
            st.session_state[state_key] = res

    # If an explanation exists in session state for this run, render it
    if state_key in st.session_state:
        saved_res = st.session_state[state_key]
        render_explanation_panel(saved_res, title=title)
